import { readFileSync, writeFileSync } from "node:fs";

const schema = JSON.parse(readFileSync(new URL("../openapi.json", import.meta.url)));
const names = Object.keys(schema.components?.schemas ?? {}).sort();
const identifier = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
const lines = [
  "/** Generated by `npm run generate:api`; do not edit. */",
  'import type { components } from "./openapi.generated";',
  "",
];
for (const name of names) {
  if (identifier.test(name)) {
    lines.push(`export type ${name} = components["schemas"]["${name}"];`);
  }
}
lines.push("");
writeFileSync(new URL("../src/api/types.ts", import.meta.url), lines.join("\n"));
